sampleAnimationCurve( curve, time, fallback ) {

	if ( ! curve || curve.times.length === 0 ) return fallback;
	const times = curve.times, values = curve.values;
	if ( time <= times[ 0 ] ) return values[ 0 ];
	const last = times.length - 1;
	if ( time >= times[ last ] ) return values[ last ];
	let lo = 0, hi = last;
	while ( hi - lo > 1 ) {
		const mid = ( lo + hi ) >> 1;
		if ( times[ mid ] <= time ) lo = mid;
		else hi = mid;
	}
	const alpha = ( time - times[ lo ] ) / ( times[ hi ] - times[ lo ] );
	// Preview approximation: raw FBX auto/cubic tangents are not evaluated here.
	return values[ lo ] + alpha * ( values[ hi ] - values[ lo ] );

}

getKeyframeTrackValues( times, curves, initialValue ) {

	const values = [];
	for ( const time of times ) {
		for ( const [ index, axis ] of [ 'x', 'y', 'z' ].entries() ) {
			values.push( this.sampleAnimationCurve( curves[ axis ], time, initialValue[ index ] ) );
		}
	}
	return values;

}
